const debounce = (fn, delay) => {
  // fn = the function to run, delay = how long to wait after the last call
  let timer;

  return function (...args) {
    // Cancel the previous timer if one was already running
    clearTimeout(timer);

    timer = setTimeout(() => {
      fn(...args);
    }, delay);
  };
};

const search = (text) => {
  console.log(`Searching: ${text}`);
};

const debounceSearch = debounce(search, 1000);

debounceSearch("J");
debounceSearch("Je");
debounceSearch("Jee");
debounceSearch("Jeet");
// Only "Searching: Jeet" gets logged, 1000ms after the last call
